test('invoiceTotals with bulk discount (qty >= 10)', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 10000
  // Regular discount: 0
  // Bulk discount: 2.5% of 10000 = 250
  // VAT: 21% of 9750 = 2047.5 → 2048
  assert.equal(result.value.subtotal, 10000);
  assert.equal(result.value.discount, 250);
  assert.equal(result.value.vat, 2048);
  assert.equal(result.value.total, 11798);
});

test('invoiceTotals no bulk discount with qty < 10', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 9000
  // Regular discount: 0
  // Bulk discount: 0 (qty < 10)
  // VAT: 21% of 9000 = 1890
  assert.equal(result.value.subtotal, 9000);
  assert.equal(result.value.discount, 0);
  assert.equal(result.value.vat, 1890);
  assert.equal(result.value.total, 10890);
});

test('invoiceTotals bulk discount applied after line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 10000
  // Line discount: 10% of 10000 = 1000
  // After line discount: 9000
  // Bulk discount: 2.5% of 9000 = 225
  // Total discount: 1225
  // VAT: 21% of 8775 = 1842.75 → 1843
  assert.equal(result.value.subtotal, 10000);
  assert.equal(result.value.discount, 1225);
  assert.equal(result.value.vat, 1843);
  assert.equal(result.value.total, 9618);
});

test('invoiceTotals bulk discount with multiple bulk-eligible lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { qty: 20, unitPrice: 500, vatRate: 9, discountPercent: 0 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 10000, bulk discount = 250, net = 9750, VAT = 2048
  // Line 2: 10000, bulk discount = 250, net = 9750, VAT = 878
  assert.equal(result.value.subtotal, 20000);
  assert.equal(result.value.discount, 500);
  assert.equal(result.value.vat, 2926);
});

test('invoiceTotals mixed bulk and non-bulk lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { qty: 5, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1 (bulk): 10000 - 250 = 9750, VAT = 2048
  // Line 2 (no bulk): 5000, VAT = 1050
  // Total discount: 250
  assert.equal(result.value.subtotal, 15000);
  assert.equal(result.value.discount, 250);
  assert.equal(result.value.vat, 3098);
});

test('invoiceTotals bulk discount at threshold (exactly 10)', () => {
