  assert.equal(invoice.lines.length, originalLineCount);
});

test('removeLine maintains other lines unchanged', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
