test('invoiceTotals with multiple discounts and voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // Gold (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'LOYALTY', amount: 5000 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.ok, true);
  // subtotal = 95000
  // line discount (5%) = 4750, net = 90250
  // bulk discount (2.5% of 90250) = 2256, total discount = 7006
  // vat = 18480 (21% of 87994)
  // voucher = 5000
  // total = 95000 - 7006 + 18480 - 5000 = 101474
  assert.equal(totals.value.subtotal, 95000);
  assert.equal(totals.value.discount, 7006);
  assert.equal(totals.value.vat, 18480);
  assert.equal(totals.value.voucher, 5000);
  assert.equal(totals.value.total, 101474);
});

