test('invoiceTotals returns subtotal, discount, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 95000); // 10 * 9500
  // line discount = 95000 * 10 / 100 = 9500, net = 85500
  // bulk discount = 2.5% of 85500 = 2137.5 → 2138, total discount = 11638
  assert.equal(result.value.discount, 11638);
  // VAT = 21% of 83362 = 17506.02 → 17506
  assert.equal(result.value.vat, 17506);
  assert.equal(result.value.total, 100868); // 95000 - 11638 + 17506
});

