  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 95000); // 10 * 9500
  // line discount = 95000 * 10 / 100 = 9500, net = 85500
  // bulk discount = 2.5% of 85500 = 2137.5 → 2138, total discount = 11638
