test('invoiceTotals with tier discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // Gold (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 10 * 9500 = 95000, 5% discount = 4750
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 95000);
  // line discount (5%) = 4750, net = 90250
  // bulk discount (2.5% of 90250) = 2256, total discount = 7006
  assert.equal(totals.value.discount, 7006);
  // vat = 21% of 87994 = 18480
  assert.equal(totals.value.vat, 18480);
  // total = 95000 - 7006 + 18480 = 106474
  assert.equal(totals.value.total, 106474);
});

test('invoiceTotals includes VAT field', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // Standard (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500, no discount, 21% VAT
  }).value;

