        name: 'Big Item',
        qty: 100,
        unitPrice: 100000, // 10000 euros
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  // 10 days overdue: total = 10000000 + 2100000 = 12100000
  // fee = 12100000 * 10 * 0.0004 = 48400 cents = 484 euros

  const result = lateFee(largeInvoice, '2026-11-14');

  assert.equal(result.ok, true);
  assert.equal(result.value, 48400);
});

test('lateFee with long overdue period', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-10-19, total is 11495
  // 70 days overdue (2026-10-19 to 2026-12-28): 11495 * 70 * 0.0004 = 322.26 → 322 cents

  const result = lateFee(issued, '2026-12-28');

  assert.equal(result.ok, true);
  assert.equal(result.value, 322);
});

test('lateFee with small amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'STICKER', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // total is ~60 cents
  // 1 day overdue: 60 * 1 * 0.0004 = 0.024 → 0 cents (rounds down)

  const result = lateFee(issued, '2026-10-20');

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lateFee with EOM payment terms', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-10-31
  // 5 days overdue: 11495 * 5 * 0.0004 = 22.99 → 23 cents

  const result = lateFee(issued, '2026-11-05');

  assert.equal(result.ok, true);
  assert.equal(result.value, 23);
});

test('lateFee with multiple partial payments', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // Total: 57475

  const paid1 = recordPayment(issued, { amount: 10000, date: '2026-10-20' }).value;
  const paid2 = recordPayment(paid1, { amount: 15000, date: '2026-10-25' }).value;
  // Remaining: 32475
  // 5 days overdue (dueDate 2026-10-19): 32475 * 5 * 0.0004 = 64.95 → 65 cents

  const result = lateFee(paid2, '2026-10-24');

  assert.equal(result.ok, true);
  assert.equal(result.value, 65);
});

test('lateFee does not mutate invoice', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  const originalStatus = issued.status;
  const originalDueDate = issued.dueDate;

  lateFee(issued, '2026-10-25');

  assert.equal(issued.status, originalStatus);
  assert.equal(issued.dueDate, originalDueDate);
});

